CREATE TABLE schema_migrations (version INT PRIMARY KEY, applied_at VARCHAR(32) NOT NULL);
CREATE TABLE users (id VARCHAR(64) PRIMARY KEY, login VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', metadata LONGTEXT NOT NULL, test INT NOT NULL DEFAULT 0, created_at VARCHAR(32) NOT NULL);
CREATE TABLE study (id INT PRIMARY KEY, closed_at VARCHAR(32), reason LONGTEXT, actor VARCHAR(64), FOREIGN KEY(actor) REFERENCES users(id));
INSERT INTO study (id) VALUES (1);
CREATE TABLE cases (id VARCHAR(64) PRIMARY KEY, title VARCHAR(255) NOT NULL, position INT NOT NULL, status VARCHAR(20) NOT NULL, practice INT NOT NULL DEFAULT 0, test INT NOT NULL DEFAULT 0, current_version VARCHAR(64), stop_access INT NOT NULL DEFAULT 0, rubric_id VARCHAR(64));
CREATE TABLE case_versions (id VARCHAR(64) PRIMARY KEY, case_id VARCHAR(64) NOT NULL, version INT NOT NULL, body LONGTEXT NOT NULL, instructions LONGTEXT NOT NULL, notes LONGTEXT NOT NULL, created_at VARCHAR(32) NOT NULL, UNIQUE(case_id,version), FOREIGN KEY(case_id) REFERENCES cases(id));
CREATE TABLE assignments (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, case_id VARCHAR(64) NOT NULL, active INT NOT NULL DEFAULT 1, UNIQUE(user_id,case_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(case_id) REFERENCES cases(id));
CREATE TABLE applications (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, case_id VARCHAR(64) NOT NULL, version_id VARCHAR(64) NOT NULL, state VARCHAR(20) NOT NULL, revision INT NOT NULL DEFAULT 0, draft LONGTEXT NOT NULL, active_request VARCHAR(64), initial_at VARCHAR(32), submitted_at VARCHAR(32), last_section VARCHAR(30), last_activity VARCHAR(32), excluded INT NOT NULL DEFAULT 0, exclusion_reason LONGTEXT, created_at VARCHAR(32) NOT NULL, UNIQUE(user_id,case_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(case_id) REFERENCES cases(id), FOREIGN KEY(version_id) REFERENCES case_versions(id));
CREATE TABLE draft_revisions (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, revision INT NOT NULL, previous_revision INT, body LONGTEXT NOT NULL, created_at VARCHAR(32) NOT NULL, UNIQUE(app_id,revision), FOREIGN KEY(app_id) REFERENCES applications(id));
CREATE TABLE snapshots (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, kind VARCHAR(20) NOT NULL, body LONGTEXT NOT NULL, revision INT NOT NULL, created_at VARCHAR(32) NOT NULL, UNIQUE(app_id,kind), FOREIGN KEY(app_id) REFERENCES applications(id));
CREATE TABLE messages (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, seq INT NOT NULL, role VARCHAR(20) NOT NULL, content LONGTEXT NOT NULL, status VARCHAR(20) NOT NULL, request_id VARCHAR(64) NOT NULL, created_at VARCHAR(32) NOT NULL, UNIQUE(app_id,seq), FOREIGN KEY(app_id) REFERENCES applications(id));
CREATE TABLE ai_requests (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, client_key VARCHAR(100) NOT NULL, attempt VARCHAR(64) NOT NULL, status VARCHAR(20) NOT NULL, model VARCHAR(100) NOT NULL, directive VARCHAR(50) NOT NULL, payload LONGTEXT NOT NULL, started_at VARCHAR(32) NOT NULL, completed_at VARCHAR(32), error VARCHAR(100), UNIQUE(app_id,client_key), FOREIGN KEY(app_id) REFERENCES applications(id));
CREATE TABLE ai_attempts (id VARCHAR(64) PRIMARY KEY, request_id VARCHAR(64) NOT NULL, status VARCHAR(20) NOT NULL, started_at VARCHAR(32) NOT NULL, completed_at VARCHAR(32), error VARCHAR(100), FOREIGN KEY(request_id) REFERENCES ai_requests(id));
CREATE TABLE events (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, client_key VARCHAR(100) NOT NULL, tab_id VARCHAR(64) NOT NULL, session_id VARCHAR(64) NOT NULL, client_seq INT NOT NULL, client_at VARCHAR(32), received_at VARCHAR(32) NOT NULL, type VARCHAR(60) NOT NULL, section VARCHAR(30) NOT NULL, payload LONGTEXT NOT NULL, quality VARCHAR(60) NOT NULL, UNIQUE(app_id,client_key), FOREIGN KEY(app_id) REFERENCES applications(id));
CREATE INDEX events_app_time ON events(app_id,received_at);
CREATE TABLE definitions (id VARCHAR(64) PRIMARY KEY, family VARCHAR(20) NOT NULL, name VARCHAR(255) NOT NULL, version INT NOT NULL, parent_id VARCHAR(64), body LONGTEXT NOT NULL, archived INT NOT NULL DEFAULT 0, created_at VARCHAR(32) NOT NULL, FOREIGN KEY(parent_id) REFERENCES definitions(id));
CREATE TABLE message_labels (id VARCHAR(64) PRIMARY KEY, message_id VARCHAR(64) NOT NULL, definition_id VARCHAR(64) NOT NULL, source VARCHAR(20) NOT NULL, review_id VARCHAR(64) NOT NULL, actor VARCHAR(64) NOT NULL, reason LONGTEXT NOT NULL, created_at VARCHAR(32) NOT NULL, FOREIGN KEY(message_id) REFERENCES messages(id), FOREIGN KEY(definition_id) REFERENCES definitions(id), FOREIGN KEY(actor) REFERENCES users(id));
CREATE TABLE label_reviews (id VARCHAR(64) PRIMARY KEY, message_id VARCHAR(64) NOT NULL, actor VARCHAR(64) NOT NULL, reason LONGTEXT NOT NULL, created_at VARCHAR(32) NOT NULL, FOREIGN KEY(message_id) REFERENCES messages(id), FOREIGN KEY(actor) REFERENCES users(id));
CREATE TABLE analysis_runs (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, rubric_id VARCHAR(64) NOT NULL, created_at VARCHAR(32) NOT NULL, FOREIGN KEY(app_id) REFERENCES applications(id), FOREIGN KEY(rubric_id) REFERENCES definitions(id));
CREATE TABLE analysis_steps (id VARCHAR(64) PRIMARY KEY, run_id VARCHAR(64) NOT NULL, step INT NOT NULL, attempt INT NOT NULL, status VARCHAR(20) NOT NULL, input LONGTEXT NOT NULL, output LONGTEXT NOT NULL, error VARCHAR(100), model VARCHAR(100) NOT NULL, directive VARCHAR(50) NOT NULL, created_at VARCHAR(32) NOT NULL, UNIQUE(run_id,step,attempt), FOREIGN KEY(run_id) REFERENCES analysis_runs(id));
CREATE TABLE decisions (id VARCHAR(64) PRIMARY KEY, step_id VARCHAR(64) NOT NULL, actor VARCHAR(64) NOT NULL, action VARCHAR(30) NOT NULL, body LONGTEXT NOT NULL, reason LONGTEXT NOT NULL, created_at VARCHAR(32) NOT NULL, FOREIGN KEY(step_id) REFERENCES analysis_steps(id), FOREIGN KEY(actor) REFERENCES users(id));
CREATE TABLE research_notes (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, actor VARCHAR(64) NOT NULL, body LONGTEXT NOT NULL, reason LONGTEXT NOT NULL, created_at VARCHAR(32) NOT NULL, FOREIGN KEY(app_id) REFERENCES applications(id), FOREIGN KEY(actor) REFERENCES users(id));
CREATE TABLE reports (id VARCHAR(64) PRIMARY KEY, app_id VARCHAR(64) NOT NULL, run_id VARCHAR(64) NOT NULL, version INT NOT NULL, body LONGTEXT NOT NULL, approved_at VARCHAR(32), published_at VARCHAR(32), actor VARCHAR(64) NOT NULL, created_at VARCHAR(32) NOT NULL, UNIQUE(app_id,version), FOREIGN KEY(app_id) REFERENCES applications(id), FOREIGN KEY(run_id) REFERENCES analysis_runs(id), FOREIGN KEY(actor) REFERENCES users(id));
CREATE TABLE audit (id VARCHAR(64) PRIMARY KEY, actor VARCHAR(64) NOT NULL, action VARCHAR(60) NOT NULL, target VARCHAR(64) NOT NULL, reason LONGTEXT NOT NULL, detail LONGTEXT NOT NULL, created_at VARCHAR(32) NOT NULL, FOREIGN KEY(actor) REFERENCES users(id));
CREATE TABLE rate_limits (id VARCHAR(100) PRIMARY KEY, count INT NOT NULL, window_start INT NOT NULL);
